void AppFontZh_DrawText(uint16_t x, uint16_t y, const uint16_t *text, uint16_t count, uint32_t color, uint32_t background)
{
  uint16_t i, row, col;
  BSP_LCD_SetTextColor(background);
  for (i = 0U; i < count; i++) BSP_LCD_FillRect((uint16_t)(x + i * 16U), y, 16U, 16U);
  BSP_LCD_SetTextColor(color);
  for (i = 0U; i < count; i++) {
    uint16_t g;
    for (g = 0U; g < (uint16_t)(sizeof(glyphs) / sizeof(glyphs[0])); g++) {
      if (glyphs[g].codepoint == text[i]) {
        for (row = 0U; row < 16U; row++) for (col = 0U; col < 16U; col++) if ((glyphs[g].rows[row] & (uint16_t)(1U << (15U - col))) != 0U) BSP_LCD_DrawPixel((uint16_t)(x + i * 16U + col), (uint16_t)(y + row), color);
        break;
      }
    }
  }
}
